/**
 * A fictional foundation range used to demo shade matching. Not real products.
 * 30 shades = 10 depths x 3 undertones, laid out evenly in CIELAB (depth = L*, undertone = hue angle 48°/58°/68°),
 * generated by a formula rather than picked by hand (see scripts/ — the range was not tuned to any one face).
 * Matching = nearest shade to YouCam Skin Tone Analysis `skin_color` by CIEDE2000 (ΔE00), the standard
 * perceptual colour difference: ≤2 is hard to see, 2–3.5 close, 3.5–5 noticeable, >5 a visible mismatch.
 */
export interface Shade { code: string; name: string; hex: string; undertone: "cool" | "neutral" | "warm" }

